'use strict';

/**
 * Link integrity for markup generated by cv-render.js.
 *
 * references.test.js can only see href/src values physically present in HTML
 * and CSS. Certificate, project, and contact links are inserted by JavaScript
 * after load, so the files they point at had no existence check. This renders
 * every CV shell with the same profile/format/base attributes the browser uses,
 * then resolves every generated local href against that shell's directory.
 */

const { test } = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { ROOT } = require('./helpers');

const CV_DATA = require(path.join(ROOT, 'js', 'cv-data.js'));
const CVRenderer = require(path.join(ROOT, 'js', 'cv-render.js'));

/** Every CV shell, including cv/engagement/. */
function cvShells() {
  const shells = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.name.endsWith('.html')) shells.push(full);
    }
  };
  walk(path.join(ROOT, 'portfolio', 'cv'));
  return shells.sort();
}

/** Read a data-* attribute from the cv-init script tag. */
function dataAttr(html, name) {
  const match = new RegExp(`data-${name}="([^"]*)"`).exec(html);
  return match ? match[1] : null;
}

function renderShell(shell) {
  const html = fs.readFileSync(shell, 'utf8');
  const profileKey = dataAttr(html, 'profile');
  const format = dataAttr(html, 'format');
  const base = dataAttr(html, 'base');
  const profile = CV_DATA.cvProfiles[profileKey];

  assert.ok(profile, `${path.relative(ROOT, shell)} references unknown profile "${profileKey}"`);

  if (format === 'engagement') {
    return {
      profileKey,
      html: CVRenderer.renderEngagement(profile, CV_DATA, { format, base }),
    };
  }

  return {
    profileKey,
    html: CVRenderer.renderCV(profile, CV_DATA, base ? { base } : undefined),
  };
}

const isLocal = (href) =>
  href &&
  !/^(?:https?:|mailto:|tel:|javascript:|data:|#)/i.test(href);

function localHrefs(html) {
  return [...html.matchAll(/\shref="([^"]*)"/g)]
    .map((match) => match[1])
    .filter(isLocal);
}

test('every local link generated by cv-render.js resolves to a real file', () => {
  const shells = cvShells();
  assert.ok(shells.length >= 20, `expected all CV shells, found ${shells.length}`);

  const missing = [];
  let checked = 0;

  for (const shell of shells) {
    const relShell = path.relative(ROOT, shell);
    const { html } = renderShell(shell);
    const hrefs = localHrefs(html);
    checked += hrefs.length;

    for (const href of hrefs) {
      const clean = href.split('#')[0].split('?')[0];
      const target = path.resolve(path.dirname(shell), clean);
      if (!fs.existsSync(target)) {
        missing.push(`${relShell} -> ${href}`);
      }
    }
  }

  assert.ok(checked >= 20, `expected local rendered links, checked ${checked}`);
  assert.deepStrictEqual(missing, [], 'Generated local links point at missing files');
});

test('every generated target="_blank" link carries opener protection', () => {
  const shells = cvShells();
  const unsafe = [];
  let external = 0;

  for (const shell of shells) {
    const relShell = path.relative(ROOT, shell);
    const { html } = renderShell(shell);

    for (const match of html.matchAll(/<a\s+([^>]*)>/g)) {
      const attrs = match[1];
      const href = /\bhref="([^"]*)"/.exec(attrs)?.[1] ?? '';
      if (!/target="_blank"/.test(attrs)) continue;
      if (!/^https?:/i.test(href)) continue;

      external++;
      if (!/rel="[^"]*noopener/i.test(attrs)) {
        unsafe.push(`${relShell}: ${href}`);
      }
    }
  }

  assert.ok(external > 0, 'no generated external links were checked');
  assert.deepStrictEqual(unsafe, [], 'Generated external links missing rel="noopener"');
});

test('every CV shell renders its own profile and the linked certificates', () => {
  const shells = cvShells();
  const linked = CV_DATA.certifications.filter((cert) => cert.link);

  for (const shell of shells) {
    const relShell = path.relative(ROOT, shell);
    const { profileKey, html } = renderShell(shell);

    assert.ok(html.includes(CV_DATA.contact.name), `${relShell}: missing contact name`);
    for (const cert of linked) {
      assert.ok(html.includes(cert.title), `${relShell} (${profileKey}): missing "${cert.title}"`);
    }
  }
});
